int FindMin(int[] a) {
    int lo = 0, hi = a.Length - 1;          // минимум в [lo..hi]
    while (lo < hi) {
        int mid = lo + (hi - lo) / 2;       // mid < hi
        if (a[mid] > a[hi]) lo = mid + 1;   // падение правее mid
        else hi = mid;                      // [mid..hi] отсортирован
    }
    return lo;                              // индекс минимума = сдвиг
}
// FindMin([4, 5, 6, 7, 0, 1, 2]) == 4: повернули на 4

